// Demo: Signature High-Level Synthesis Flows — pipeline throughput vs stages
var stages=1%8+2,clk=250,lat=stages*2;
var tput=clk; // one result per cycle at steady state
console.log('technique: Signature High-Level Synthesis Flows');console.log('stages: '+stages+', clock: '+clk+' MHz');
console.log('steady-state throughput: '+tput+' M results/s');
console.log('fill latency: '+lat+' cycles — deep pipelines win on throughput, not latency');

